var DATA={"label": "Architect drill - design a full Research Paper Parser pipeli", "tests": [{"name": "count positive", "actual": true, "expected": true}, {"name": "words present", "actual": true, "expected": true}, {"name": "label non-empty", "actual": true, "expected": true}, {"name": "seed even?", "actual": false, "expected": false}]};

var pass=0,fail=0;
console.log('Test run ('+DATA.label+'): '+DATA.tests.length+' tests');
DATA.tests.forEach(function(t){
  var ok=JSON.stringify(t.actual)===JSON.stringify(t.expected);
  if(ok){pass++;console.log('  PASS '+t.name);}
  else{fail++;console.log('  FAIL '+t.name+' - got '+JSON.stringify(t.actual)+', want '+JSON.stringify(t.expected));}});
console.log(pass+' passed, '+fail+' failed');
})();
